            elif "PLAINS" in t_type: terrain = "PLAINS"
            elif "DESERT" in t_type: terrain = "DESERT"
            elif "TUNDRA" in t_type: terrain = "TUNDRA"
            elif "SNOW" in t_type: terrain = "SNOW"
        else:
            if "GRASS" in t_type: terrain = "GRASS"
            elif "PLAINS" in t_type: terrain = "PLAINS"
            elif "DESERT" in t_type: terrain = "DESERT"
            elif "TUNDRA" in t_type: terrain = "TUNDRA"
            elif "SNOW" in t_type: terrain = "SNOW"
            elif "COAST" in t_type: terrain = "COAST"
            elif "OCEAN" in t_type: terrain = "OCEAN"

        tiles[row["ID"]] = {
            "x": row["ID"] % width,
            "y": row["ID"] // width,
            "terrain": terrain,
            "is_hills": is_hills,
            "is_impassable": bool(row["IsImpassable"]),
            "feature": None,
            "resource": None,
