    for row in cursor.fetchall():
        tiles[row["ID"]]["feature"] = row["FeatureType"]
        if "FLOODPLAINS" in row["FeatureType"]:
            tiles[row["ID"]]["is_floodplains"] = True

    # Resources
    cursor.execute("SELECT ID, ResourceType FROM PlotResources")
    for row in cursor.fetchall():
        tiles[row["ID"]]["resource"] = row["ResourceType"]
        # Need to determine resource type (STRATEGIC, LUXURY, BONUS)
        # For this scenario, we saw no resources, but let's be safe.
        res = row["ResourceType"]
        if res in ("RESOURCE_IRON", "RESOURCE_HORSES", "RESOURCE_NITER", "RESOURCE_COAL", "RESOURCE_OIL", "RESOURCE_ALUMINUM", "RESOURCE_URANIUM"):
            tiles[row["ID"]]["resource_type"] = "STRATEGIC"
        elif res in ("RESOURCE_WHEAT", "RESOURCE_RICE", "RESOURCE_MAIZE", "RESOURCE_BANANAS", "RESOURCE_CATTLE", "RESOURCE_SHEEP", "RESOURCE_DEER", "RESOURCE_FISH", "RESOURCE_CRABS", "RESOURCE_COPPER", "RESOURCE_STONE"):
            tiles[row["ID"]]["resource_type"] = "BONUS"
        else:
            tiles[row["ID"]]["resource_type"] = "LUXURY"

    # Rivers
    cursor.execute("SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers")
    for row in cursor.fetchall():
        if row["IsNEOfRiver"]: tiles[row["ID"]]["river_edges"].append(1)
        if row["IsNWOfRiver"]: tiles[row["ID"]]["river_edges"].append(2)
        if row["IsWOfRiver"]: tiles[row["ID"]]["river_edges"].append(3)

